import {initialState,reduce,validateState,correctResearch,readyToLeave,heardEssentials,ITEM_IDS} from './state.js';
import {sources,slots,items,dialogue,hints} from './data.js';
const KEY='tamatem-dina-prolog-v1';
const $=s=>document.querySelector(s);
const asset=name=>globalThis.TD_ASSETS?.[name]||'./assets/'+name;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),savedAt=null,storageAvailable=true,feedback='',showMarkers=true,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){state=validateState(saved.state);savedAt=saved.savedAt;}}catch{storageAvailable=false;}
const icons={book:'<path d="M3 5q5-2 9 1 4-3 9-1v15q-5-2-9 1-4-3-9-1Z"/><path d="M12 6v15"/>',leaf:'<path d="M5 19C-1 7 10 2 21 3c0 11-5 20-16 16ZM5 19 16 8"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16"/>',flower:'<circle cx="12" cy="12" r="2"/><path d="M12 10C2 0 21-2 14 10 27 3 28 20 14 14 21 27 3 28 10 14-3 20-3 3 10 10 3-3 21-3 12 10Z"/>',paper:'<path d="M5 2h10l4 4v16H5ZM15 2v5h4M8 11h8M8 15h8M8 19h5"/>',lens:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',lantern:'<path d="M7 8h10l3 13H4ZM8 8V6a4 4 0 0 1 8 0v2M5 21h14M12 12v5"/>',rope:'<path d="M8 20C-4 8 7-2 14 5c8 8-2 19-8 11-3-4 3-11 7-7s-1 10-5 7M15 16l7 6"/>',glass:'<path d="M9 2h6v6l4 5v9H5v-9l4-5ZM9 5h6M5 15h14"/>',arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',check:'<path d="m5 12 5 5L21 5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01"/>',bag:'<path d="M7 6V4h10v2M6 6h12l2 16H4ZM8 12h8v6H8ZM8 6v3M16 6v3"/>'};
const icon=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.paper}</svg>`;
const button=(action,label,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const avatar=name=>`<span class="portrait ${name==='Dina'?'dina':'tamatem'}" aria-hidden="true"></span>`;
const meta={intro:['01','Die Lumenblüte','Dina'],research:['01','Der gemeinsame Arbeitstisch','Dina'],illness:['02','Als das Licht kühler wurde','Tamatem'],resolve:['03','Der leere Rucksack','Tamatem'],pack:['04','Was Dina vorbereitet hat','Tamatem'],threshold:['05','Hinter der letzten Laterne','Tamatem'],complete:['05','Der erste Schritt','Tamatem']};
function persist(){savedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify({state,savedAt}));storageAvailable=true;}catch{storageAvailable=false;}}
function dispatch(action){const old=state.stage;state=reduce(state,action);persist();render();if(old!==state.stage){$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function openModal(content){$('#modal-body').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modal-body').scrollTop=0;}
function closeModal(){$('#modal').close();}
function heading(kicker,title){return `<p class="eyebrow">${kicker}</p><h2 id="modal-title">${title}</h2>`;}
function dialogueBox(name,text,small=''){return `<div class="dialogue-box">${avatar(name)}<div><div class="speaker">${esc(name)}${small?`<span>${esc(small)}</span>`:''}</div><p>${text}</p></div></div>`;}
function scene(image,caption,hotspots='',cls=''){return `<div class="scene ${cls}"><img src="${asset(image+'.png')}" alt="${esc(caption)}" draggable="false">${hotspots}<div class="scene-caption"><span class="scene-corner">${meta[state.stage][0]}</span><span>${esc(caption)}</span></div></div>`;}
function chapter(){const m=meta[state.stage];return `<div class="chapter-heading"><div><p class="eyebrow">Kapitel 01 <span class="eyebrow-line"></span> Alter 6</p><h1>${m[1]}</h1></div><span class="chapter-progress" aria-label="Abschnitt ${m[0]} von 5">${m[0]}<span> / 05</span></span></div>`;}
function actor(){const name=meta[state.stage][2];return `<div class="actor-strip">${avatar(name)}<div><small>Du spielst</small><strong>${name}</strong></div><span class="save-indicator">${storageAvailable?'Automatisch gespeichert':'Speichern nicht verfügbar'}</span></div>`;}
function tools(){return `<div class="scene-tools">${button('markers',icon('lens')+'<span>Fundstücke zeigen</span>','tool-button '+(showMarkers?'active':''),'aria-pressed="'+showMarkers+'"')}${button('hint',icon('help')+'<span>Hinweis</span>','tool-button')}</div>`;}
function intro(){return `<section class="cover"><img class="cover-art" src="${asset('workroom.png')}" alt="Tamatem und Dina recherchieren gemeinsam an ihrem Arbeitstisch."><div class="cover-shade"></div><div class="cover-copy"><p class="eyebrow light">Ein Comic-Adventure</p><h1>Zwischen<br>den Zeilen<span>.</span></h1><p class="cover-subtitle">Sieben Abenteuer. Zwei Gefährten.<br>Und die Frage, was es heißt, mutig zu sein.</p><div class="cover-start">${button('start','Die Lumenblüte beginnen '+icon('arrow'),'button amber')}<span>Erster spielbarer Abschnitt · etwa 5 Minuten</span></div></div><div class="cover-foot"><span>01 <i>Die Lumenblüte</i></span><span>Tamatem · 6 Jahre</span></div></section><div class="intro-note"><p>Erkunde die Bilder, lies zwischen den Zeilen und verbinde die Hinweise.</p><span>Mit Maus, Tastatur oder durch Antippen.</span></div>`;}
function research(){
 const marks=Object.entries(sources).map(([id,s],i)=>`<button class="hotspot ${state.read.includes(id)?'visited':''} ${showMarkers?'shown':''}" style="--x:${{field:68,travel:22,drawing:34,advert:86}[id]}%;--y:${{field:66,travel:87,drawing:67,advert:72}[id]}%" data-action="source" data-id="${id}" aria-label="${s.title} untersuchen"><span>${i+1}</span><b>${s.title}</b></button>`).join('');
 const shelf=`<div class="source-shelf">${Object.entries(sources).map(([id,s],i)=>`<button class="source-tab ${state.read.includes(id)?'read':''}" data-action="source" data-id="${id}"><span class="source-number">0${i+1}</span><span>${s.title}<small>${state.read.includes(id)?'Gelesen':'Untersuchen'}</small></span>${state.read.includes(id)?icon('check'):icon(s.symbol)}</button>`).join('')}</div>`;
 const card=Object.entries(slots).map(([id,s])=>`<button class="evidence-slot ${state.assign[id]?'filled':''} ${state.committed?'confirmed':''}" data-action="slot" data-id="${id}" ${state.committed?'disabled':''}><span class="slot-label">${s.short}</span><span>${state.assign[id]?sources[state.assign[id]].title:s.title}</span><small>${state.assign[id]?(state.committed?'Bestätigter Beleg':'Quelle ändern'):'Beleg auswählen'}</small>${state.committed?icon('check'):icon('paper')}</button>`).join('');
 return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom','Ein Nachmittag am gemeinsamen Arbeitstisch.',marks)}${tools()}${dialogueBox('Dina',state.committed?'Drei Belege. Drei verschiedene Fragen. Jetzt wissen wir, was der Bericht wirklich trägt.':'Der Artikel braucht mehr als eine schöne Geschichte. Was wissen wir über diese Blüte – und woher?','Journalistin')}<div class="scene-subnote">${state.read.length} von 4 Quellen gelesen</div></section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">Dinas Recherche</span>${icon('book')}</div><h2>Was lässt sich<br>belegen?</h2><p class="panel-intro">Lies die Unterlagen auf dem Tisch. Ordne jeder Frage eine passende Quelle zu.</p>${shelf}<div class="research-divider"><span>Die Recherchekarte</span><i></i></div><div class="evidence-slots">${card}</div>${feedback?`<p class="feedback" role="status">${esc(feedback)}</p>`:''}${state.committed?`<p class="success-line">${icon('check')} Die Karte ist vollständig.</p>${button('research-next','Die Mappe schließen '+icon('arrow'),'button wide')}`:button('verify','Recherchekarte prüfen '+icon('arrow'),'button wide')}</aside></div>`;
}
function illness(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('illness','Einige Stunden später. Das Fieber ist gestiegen.')}<div class="time-slip"><span>Die Ärztin bleibt bei Dina.</span><span>Der Bericht bietet eine mögliche Chance.</span></div>${dialogueBox('Tamatem','Gestern haben wir über diesen Bericht gelacht. Jetzt zähle ich die Zeilen, als könnte ich darin etwas übersehen haben.')} ${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">Ein anderer Abend</span>${icon('book')}</div><h2>Was bleibt,<br>wenn Wissen fehlt?</h2><p class="panel-intro">Sprich mit Dina und der Ärztin, bevor du entscheidest, was du tust.</p><div class="conversation-list">${Object.entries(dialogue).map(([id,d])=>button('talk',`<span>${d.title}<small>${state.talked.includes(id)?'Gespräch erneut lesen':'Zuhören'}</small></span>${icon(state.talked.includes(id)?'check':'arrow')}`,'conversation','data-id="'+id+'"')).join('')}</div><div class="aside-quote">„Eine mögliche Hilfe.<br>Keine Sicherheit.“<span>Die Ärztin</span></div>${button('illness-next','Zurück zum Arbeitstisch '+icon('arrow'),'button wide',heardEssentials(state)?'':'disabled')}<p class="microcopy">${heardEssentials(state)?'Du weißt, wer sich um Dina kümmert.':'Höre zuerst Dina und der Ärztin zu.'}</p></aside></div>`;}
function resolve(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom','Der Raum ist derselbe. Nichts fühlt sich mehr so an.','','evening')}${dialogueBox('Tamatem','Ich kann den Weg beschreiben. Ich kann die Blüte erkennen. Aber ich kann nicht ausrechnen, ob ich rechtzeitig zurück bin.')}<div class="narrative-note">Der leere Rucksack steht unter dem Tisch.<br>Zum ersten Mal fühlt sich Vorbereitung nicht wie Sicherheit an.</div>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">Eine Entscheidung</span>${icon('bag')}</div><h2>Was sagst du<br>dir selbst?</h2><p class="panel-intro">Du musst noch nicht furchtlos sein.</p><div class="choice-list">${button('choose','„Ich habe Angst, dass ich zu spät komme.“','choice '+(state.choice==='fear'?'selected':''),'data-id="fear" aria-pressed="'+(state.choice==='fear')+'"')}${button('choose','„Ich muss zuerst den Bericht verstehen.“','choice '+(state.choice==='research'?'selected':''),'data-id="research" aria-pressed="'+(state.choice==='research')+'"')}</div>${state.choice?`<p class="choice-response">${state.choice==='fear'?'Die Angst verschwindet nicht. Aber sie hat jetzt einen Namen.':'Wenn er die Zeilen noch einmal prüft, werden seine Hände ruhiger. Für einen Moment.'}</p>`:''}${button('resolve-next','Den Rucksack vorbereiten '+icon('arrow'),'button wide',state.choice?'':'disabled')}<p class="microcopy">Diese Entscheidung bleibt in deinem Spielstand.</p></aside></div>`;}
function pack(){const inventory=ITEM_IDS.map(id=>`<button class="inventory-item ${state.packed.includes(id)?'packed':''}" data-action="item" data-id="${id}" aria-label="${items[id].title}${state.packed.includes(id)?', eingepackt':''}">${icon(items[id].symbol)}<span>${items[id].title}</span><small>${state.packed.includes(id)?'Eingepackt':'Untersuchen'}</small>${state.packed.includes(id)?icon('check','item-check'):''}</button>`).join('');return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom','Was du brauchst, liegt bereits vor dir.','','evening')}${dialogueBox('Dina','Ich habe den Bericht geprüft. Ob der Garten noch dort ist, weiß ich nicht. Und du nimmst Hilfe an, wenn du welche findest.') }<div class="inventory-heading"><span>Reiseausrüstung</span><small>${state.packed.length} / 4 eingepackt</small></div><div class="inventory">${inventory}</div>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">Vor dem Aufbruch</span>${icon('bag')}</div><h2>Wissen wiegt<br>fast nichts.</h2><p class="panel-intro">Aber es muss mit. Übernimm Dinas Recherchekarte und packe die vier Gegenstände ein.</p>${button('take-note',`<span>${icon('book')}<b>Dinas Recherchemappe</b><small>${state.noteTaken?'Im Notizbuch übernommen':'Karte ansehen und mitnehmen'}</small></span>${icon(state.noteTaken?'check':'arrow')}`,'note-card '+(state.noteTaken?'taken':''))}<ul class="packing-list">${ITEM_IDS.map(id=>`<li class="${state.packed.includes(id)?'done':''}">${icon(state.packed.includes(id)?'check':items[id].symbol)}<span>${items[id].title}</span></li>`).join('')}</ul>${button('depart','Zum Waldrand '+icon('arrow'),'button wide',readyToLeave(state)?'':'disabled')}<p class="microcopy">${readyToLeave(state)?'Die Ärztin kennt deinen Weg und bleibt bei Dina.':'Karte und Ausrüstung müssen vollständig sein.'}</p></aside></div>`;}
function threshold(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('threshold','Hinter dem letzten Dorflicht beginnt der Wald.')}<div class="owl-dialogue"><span class="owl-monogram" aria-hidden="true">O</span><div><span class="speaker">Oris <span>Eine unerwartete Begleiterin</span></span><p>„Du trägst sehr viel Entschlossenheit für so wenig Gepäck.“</p></div></div>${dialogueBox('Tamatem','„Die wiegt nichts.“')}<p class="owl-reply">„Das sagen die meisten, bevor sie sie brauchen.“</p>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">Die Schwelle</span>${icon('map')}</div><h2>Allein aufbrechen.<br>Gemeinsam weiter.</h2><p class="panel-intro">Die Eule sieht dich an, als hätte sie mit dir gerechnet.</p><div class="choice-list">${button('owl','„Begleitest du mich? Ich kenne den Wald nicht.“','choice','data-id="ask"')}${button('owl','„Kennst du den Weg zum Glasberg?“','choice','data-id="directions"')}</div><p class="microcopy">Wie Tamatem Hilfe annimmt, gehört zu seiner Geschichte.</p></aside></div>`;}
function complete(){return `${chapter()}<section class="ending-panel">${scene('threshold','Oris breitet die Flügel aus. Der Weg liegt vor euch.')}<div class="ending-copy"><p class="eyebrow">Erster spielbarer Abschnitt abgeschlossen</p><h2>Die Reise<br>hat begonnen.</h2><p>${state.owlChoice==='ask'?'„Ich fliege voraus“, sagt Oris. „Du musst mir nur sagen, wenn ich zu schnell werde.“':'„Den Weg? Ja“, sagt Oris. „Aber Wege sind hier selten das ganze Problem.“'}</p><p>Du hast Dinas Recherche geprüft, eine Entscheidung getroffen und Tamatems Rucksack gepackt. Dein Fortschritt ist ${storageAvailable?'gespeichert':'gerade nur in dieser Sitzung verfügbar'}.</p><div class="next-chapter"><span>Danach folgt</span><strong>Der Fluss & der Quellgarten</strong><small>Dieser Teil ist noch in Entwicklung.</small></div><div class="ending-buttons">${button('notebook',icon('book')+' Notizbuch ansehen','button')}${button('export','Spielstand sichern','button secondary')}</div></div></section>`;}
function render(){const renders={intro,research,illness,resolve,pack,threshold,complete};$('#main').innerHTML=renders[state.stage]();$('#notebook-button').disabled=state.stage==='intro';document.title=(state.stage==='intro'?'Tamatem & Dina':meta[state.stage][1])+' – Zwischen den Zeilen';}
function showSource(id){if(!sources[id])return;dispatch({type:'READ',id});const s=sources[id];openModal(`${heading('Quelle · '+s.tag,s.title)}<div class="document-sheet"><div class="document-seal">${icon(s.symbol)}</div><p class="document-byline">${s.kicker}</p><p class="document-date">${s.date}</p>${s.text.map(t=>`<p>${esc(t)}</p>`).join('')}</div><p class="character-comment"><strong>Dina</strong> „${esc(s.comment)}“</p>${state.committed?'':`<div class="document-actions"><p>Auf der Recherchekarte verwenden für:</p>${Object.entries(slots).map(([k,v])=>button('assign',v.short,'button secondary','data-slot="'+k+'" data-id="'+id+'"')).join('')}</div>`}`);}
function showSlot(id){const s=slots[id];openModal(`${heading('Recherchekarte',s.title)}<p class="modal-intro">${s.description}</p><div class="source-chooser">${Object.entries(sources).map(([sid,src])=>button(state.read.includes(sid)?'assign':'source',`${icon(src.symbol)}<span>${src.title}<small>${state.read.includes(sid)?'Als Beleg einsetzen':'Zuerst lesen'}</small></span>${icon('arrow')}`,'conversation','data-id="'+sid+'" data-slot="'+id+'"')).join('')}</div>`);}
function showTalk(id){const d=dialogue[id];dispatch({type:'TALK',id});openModal(`${heading('Dinas Zimmer',d.title)}<div class="dialogue-transcript">${d.lines.map(([name,text])=>`<div class="transcript-line ${name==='Tamatem'?'child-line':''}"><strong>${name}</strong><p>${esc(text)}</p></div>`).join('')}</div>${button('close','Zurück ins Zimmer '+icon('arrow'),'button wide')}`);}
function showItem(id){const i=items[id];openModal(`${heading('Reiseausrüstung',i.title)}<div class="item-illustration">${icon(i.symbol)}</div><p class="item-tagline">${i.line}</p><p class="modal-intro">${i.detail}</p>${state.packed.includes(id)?`<p class="success-line">${icon('check')} Bereits im Rucksack.</p>`:button('pack','In den Rucksack legen '+icon('bag'),'button wide','data-id="'+id+'"')}`);}
function showNote(){openModal(`${heading('Dinas Recherchekarte','Drei Fragen. Drei Belege.')}<div class="notebook-entries">${Object.entries(slots).map(([k,v])=>`<article><span class="eyebrow">${v.short}</span><h3>${sources[state.assign[k]].title}</h3><p>${sources[state.assign[k]].observation}</p></article>`).join('')}</div><p class="modal-intro">Tamatem liest die Karte und übernimmt die Angaben in sein Notizbuch.</p>${state.noteTaken?'<p class="success-line">Die Karte ist bereits übernommen.</p>':button('confirm-note','Ins Notizbuch übernehmen '+icon('book'),'button wide')}`);}
function notebook(){let content='';if(state.stage==='research'||state.stage==='illness'||state.stage==='resolve'){content=`<p class="modal-intro">${state.stage==='research'?'Dinas Recherche am Arbeitstisch.':'Dinas Karte liegt noch in der Mappe. Tamatem muss sie vor dem Aufbruch selbst lesen.'}</p>`;if(state.stage==='research')content+=state.read.length?state.read.map(id=>`<article><h3>${sources[id].title}</h3><p>${sources[id].observation}</p></article>`).join(''):'<p>Noch keine Quellen untersucht.</p>';}if(state.noteTaken)content+=Object.entries(slots).map(([k,v])=>`<article><span class="eyebrow">${v.short}</span><h3>${sources[state.assign[k]].title}</h3><p>${sources[state.assign[k]].observation}</p></article>`).join('');if(['pack','threshold','complete'].includes(state.stage))content+=`<article><span class="eyebrow">Eine Entscheidung</span><h3>${state.choice==='fear'?'Die Angst benennen':'Am Bericht festhalten'}</h3><p>${state.choice==='fear'?'Ich habe Angst, dass ich zu spät komme.':'Ich muss zuerst den Bericht verstehen.'}</p></article>`;if(state.owlChoice)content+=`<article><span class="eyebrow">Am Waldrand</span><h3>Oris</h3><p>${state.owlChoice==='ask'?'Ich habe sie gebeten, mich zu begleiten.':'Ich habe sie nach dem Weg gefragt. Sie fliegt voraus.'}</p></article>`;openModal(`${heading('Beobachtungen & Entscheidungen','Das Notizbuch')}<div class="notebook-entries">${content||'<p>Die erste Seite ist noch leer.</p>'}</div>`);}
function showHint(){const list=hints[state.stage];if(!list){toast('Beginne das Abenteuer. Hinweise stehen dir während des Spiels zur Verfügung.');return}dispatch({type:'HINT'});const level=state.hints[state.stage]||1;openModal(`${heading('Rätselhilfe · Stufe '+level+' von 3','Ein Gedanke für den Weg')}<p class="hint-copy">${list[level-1]}</p><p class="microcopy">Hinweise verändern deine Geschichte nicht.</p>${level<3?button('hint','Konkreteren Hinweis zeigen','button secondary'):''}`);}
function menu(){const time=savedAt?new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit'}).format(new Date(savedAt)):'–';openModal(`${heading('Tamatem & Dina','Eine Pause ist erlaubt.')}<p class="modal-intro">${storageAvailable?'Dein Fortschritt wird nach jeder Handlung auf diesem Gerät gespeichert.':'Der Browser konnte den lokalen Spielstand nicht speichern. Sichere ihn als Datei, bevor du schließt.'}</p><div class="menu-status"><span>Aktueller Abschnitt</span><strong>${meta[state.stage][1]}</strong><small>Zuletzt gespeichert: ${esc(time)}</small></div><div class="menu-actions">${button('close','Weiterspielen '+icon('arrow'),'button wide')}${button('export','Spielstand als Datei sichern','button secondary wide')}${button('import','Spielstand aus Datei laden','button secondary wide')}${button('offline-info','Offline auf Laptop & iPhone','button secondary wide')}${button('restart-confirm','Von vorn beginnen','text-button')}</div>`);}
function exportSave(){const blob=new Blob([JSON.stringify({game:'tamatem-dina-prolog',state,savedAt},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tamatem-dina-spielstand.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Spielstand als Datei bereitgestellt.');}
function offlineInfo(){openModal(`${heading('Dein Abenteuer für unterwegs','Ohne Netz weiterspielen.')}<p class="modal-intro">${globalThis.TD_STANDALONE?'Diese Datei enthält alle Bilder, Texte und Spielfunktionen des Prologs. Auf dem Laptop kannst du sie direkt im Browser öffnen.':'Öffne diese Version einmal mit Internet und warte auf „Offline bereit“ am unteren Seitenrand. Dann sind die Dateien dieses Prologs auf dem Gerät gespeichert.'}</p><ol class="offline-instructions"><li><strong>Auf dem iPhone</strong><p>Öffne die Spieladresse in Safari. Wähle im Teilen-Menü „Zum Home-Bildschirm“ und öffne das Spiel anschließend über dieses Symbol. Lade es dort einmal vollständig.</p></li><li><strong>Auf dem Laptop</strong><p>${globalThis.TD_STANDALONE?'Bewahre diese HTML-Datei auf. Sie benötigt keinen zusätzlichen Server und keine laufende Internetverbindung.':'Nutze denselben Browser und dieselbe Adresse. Eine Installation als App ist optional.'}</p></li><li><strong>Dein Spielstand</strong><p>Er liegt auf diesem Gerät. Über die Dateisicherung kannst du ihn auf ein anderes Gerät übertragen. Browser können lokale Daten löschen; die Datei bleibt deine zusätzliche Sicherung.</p></li></ol><p class="microcopy">Die private Spieladresse kann beim erstmaligen Öffnen eine Anmeldung verlangen. Offline muss die Web-Version auf dem jeweiligen Gerät bereits vollständig geladen sein.</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 switch(a){
 case 'start':dispatch({type:'START'});break;
 case 'source':showSource(id);break;
 case 'slot':showSlot(id);break;
 case 'assign':feedback='';dispatch({type:'ASSIGN',slot:b.dataset.slot,id});closeModal();toast('Beleg auf der Recherchekarte vermerkt.');break;
 case 'verify':if(correctResearch(state)){feedback='';dispatch({type:'VERIFY'});toast('Dina hat die Recherchekarte fertiggestellt.');}else{const wrong=Object.keys(slots).filter(k=>state.assign[k]!=={property:'field',place:'travel',identity:'drawing'}[k]);feedback=wrong.some(k=>!state.assign[k])?'Es fehlen noch Belege. Lies die Quellen und besetze alle drei Felder.':'Mindestens ein Beleg beantwortet eine andere Frage. Prüfe besonders: '+slots[wrong[0]].short+'.';render();}break;
 case 'research-next':feedback='';dispatch({type:'RESEARCH_NEXT'});break;
 case 'talk':showTalk(id);break;
 case 'illness-next':dispatch({type:'ILLNESS_NEXT'});break;
 case 'choose':dispatch({type:'CHOOSE',id});break;
 case 'resolve-next':dispatch({type:'RESOLVE_NEXT'});break;
 case 'item':showItem(id);break;
 case 'pack':dispatch({type:'PACK',id});closeModal();toast(items[id].title+' eingepackt.');break;
 case 'take-note':showNote();break;
 case 'confirm-note':dispatch({type:'TAKE_NOTE'});closeModal();toast('Dinas Karte ist jetzt in Tamatems Notizbuch.');break;
 case 'depart':dispatch({type:'DEPART'});break;
 case 'owl':dispatch({type:'OWL_CHOICE',id});break;
 case 'hint':showHint();break;
 case 'markers':showMarkers=!showMarkers;render();break;
 case 'notebook':notebook();break;
 case 'close':closeModal();break;
 case 'export':exportSave();break;
 case 'import':$('#import-file').click();break;
 case 'offline-info':offlineInfo();break;
 case 'restart-confirm':openModal(`${heading('Neuer Anfang','Diesen Durchlauf neu beginnen?')}<p class="modal-intro">Der lokale Fortschritt wird ersetzt. Sichere vorher eine Datei, wenn du diesen Durchlauf behalten möchtest.</p><div class="menu-actions">${button('export','Vorher als Datei sichern','button secondary wide')}${button('restart','Ja, neu beginnen','button wide')}${button('menu','Zurück','text-button')}</div>`);break;
 case 'restart':state=initialState();feedback='';persist();closeModal();render();window.scrollTo(0,0);break;
 case 'menu':menu();break;
 }
});
$('#modal-close').addEventListener('click',closeModal);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#notebook-button').addEventListener('click',notebook);
$('#menu-button').addEventListener('click',menu);
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>128000)throw Error('Die Spielstanddatei ist zu groß.');const x=JSON.parse(await file.text());if(x.game!=='tamatem-dina-prolog')throw Error('Das ist kein Spielstand dieses Prologs.');const incoming=validateState(x.state);openModal(`${heading('Spielstand laden','Diesen Fortschritt übernehmen?')}<p class="modal-intro">Abschnitt: ${esc(meta[incoming.stage][1])}. Dein aktueller lokaler Fortschritt wird ersetzt.</p><div class="menu-actions">${button('confirm-import','Spielstand übernehmen','button wide')}${button('menu','Abbrechen','button secondary wide')}</div>`);const confirm=$('[data-action="confirm-import"]');confirm.addEventListener('click',()=>{state=incoming;feedback='';persist();closeModal();render();$('#main').focus();toast('Spielstand übernommen.');},{once:true});}catch(error){toast(error.message||'Diese Datei konnte nicht gelesen werden.');}finally{e.target.value='';}});
async function setupOffline(){const status=$('#offline-status');if(globalThis.TD_STANDALONE){status.textContent='Offline-Version · alles in dieser Datei';status.classList.add('ready');return}if(!('serviceWorker'in navigator)||!['https:','http:'].includes(location.protocol)){status.textContent='Für Offline-Laden einmal über die Spieladresse öffnen';return}try{const reg=await navigator.serviceWorker.register('./sw.js');const ready=await navigator.serviceWorker.ready;const worker=ready.active;if(worker){const channel=new MessageChannel();channel.port1.onmessage=e=>{status.textContent=e.data.ready?'Offline bereit · Prolog vollständig geladen':'Offline-Dateien noch nicht vollständig';status.classList.toggle('ready',!!e.data.ready)};worker.postMessage({type:'STATUS'},[channel.port2]);}reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Eine neue Spielversion ist bereit. Sie wird beim nächsten Öffnen geladen.');});});}catch{status.textContent='Offline-Laden nicht verfügbar · Spielstand als Datei sichern';}}
render();setupOffline();
